  /**
   * GetMe returns current user profile
   * Req example: { "user_id": "uuid" }
   * Res example: { "user": { "user_id": "...", "email": "...", "username": "...", "avatar": "...", "phone": "...", "status": "ACTIVE" }, "errors": [] }
   */
  GetMe(request: GetMeRequest): Promise<GetMeResponse>;
  /**
   * Verify checks token and permission
   * Req example: { "token":"...", "request_type":"HTTP", "method":"GET", "url":"/api" }
   * Res example: { "success": true, "errors": [] }
   */
